	{
		Attack attack = this.attack;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(EntityEventHandler));
		if (useLifeTime)
		{
			lifeStopwatchID = ChaosStopwatch.Begin(lifeTime);
		}
	}

	private void Update()
	{
		if (useLifeTime && ChaosStopwatch.Check(lifeStopwatchID))
		{
			useLifeTime = false;
			DestroyVine();
		}
		if (!markedForDestroy && anim.AnimPlayed() && (!spawnAnimPlayed || ChaosStopwatch.Check(idleStopwatchID)))
		{
			spawnAnimPlayed = true;
			idleStopwatchID = ChaosStopwatch.Begin(UnityEngine.Random.Range(0.75f, 1.5f));
		}
		if (rootedEntity != null)
		{
			MoveRootedEntity();
		}
	}

	private void EntityEventHandler(Entity otherEntity)
	{
		if (otherEntity != null)
		{
			attack.enabled = false;
			if (otherEntity.health == null || otherEntity.health.ignoreGrab)
			{
				DestroyVine();
				return;
			}
			anim.Play("Grab", -1, 0f);
			rootedEntity = otherEntity;
			movePos = transform.position;
			SoundManager.PlayAudioWithDistance("VineWhip", transform.position);
		}
	}

	private void MoveRootedEntity()
	{
		if (rootedEntity != null && movePos != Vector3.zero && Vector3.Distance(rootedEntity.transform.position, movePos) > 0.15f)
		{
			rootedEntity.rigidbody2D.MovePosition(movePos);
		}
	}

	public void EmitSpawnEffect()
	{
