using System;
using UnityEngine;

public class Tree : Destructible
{
	public enum TreeMode
	{
		Planter,
		Grass,
		FloorCrack
	}

	private bool transparentMode;

	private bool initialized;

	private static Vector3 defaultLeafEmitPos = new Vector3(0f, 3.5f, -3.5f);

	private static Vector3 lowLeafEmitPos = new Vector3(0f, 2.5f, -3.5f);

	private LeafEmitter.LeafColor leafColor;

	private SpriteRenderer trunkRenderer;

	private SpriteRenderer floorBaseRenderer;

	private SortSpriteLayer[] spriteSorters;

	public TreeMode treeMode;

	public Sprite[] spriteVars;

	public Sprite[] trunkVars;

	public Sprite[] destroyedVars;

	private bool smallTree;

	private int treeIndex;

	public bool skipRandomSprite;

	public bool skipRandomFlip;

	public bool skipLeafEmit;

	private static GameObject _prefab;

	public Sprite[] floorBaseSprites;

	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/Environment/Earth/Tree.prefab");
			}
			return _prefab;
		}
	}

	public override void Awake()
	{
		base.Awake();
		destroyedAudioID = "WoodBreak";
		Initialize();
	}

	public void Initialize()
	{
		spriteRenderer = transform.Find("TreeSprite").GetComponent<SpriteRenderer>();
		trunkRenderer = transform.Find("TreeTrunkSprite").GetComponent<SpriteRenderer>();
		shadowSprite = transform.Find("TreeShadowSprite").GetComponent<SpriteRenderer>();
		floorBaseRenderer = transform.Find("TreeFloorSprite").GetComponent<SpriteRenderer>();
		spriteSorters = GetComponentsInChildren<SortSpriteLayer>();
		if (!skipRandomFlip && (double)UnityEngine.Random.value >= 0.5)
		{
			spriteRenderer.transform.localScale = new Vector3(transform.localScale.x * -1f, transform.localScale.y, transform.localScale.z);
			trunkRenderer.transform.localScale = spriteRenderer.transform.localScale;
		}
		if (!skipRandomSprite)
		{
			int num = UnityEngine.Random.Range(0, spriteVars.Length - 1);
			spriteRenderer.sprite = spriteVars[num];
			trunkRenderer.sprite = trunkVars[num % 3];
			smallTree = num % 3 == 0;
			if (num < 3)
			{
				leafColor = LeafEmitter.LeafColor.Green;
			}
			else
			{
				leafColor = LeafEmitter.LeafColor.Purple;
			}
			floorBaseRenderer.sprite = floorBaseSprites[(int)treeMode];
		}
		if (base.health != null)
		{
			Health health = base.health;
			health.takeDamageEventHandlers = (Health.OnTakeDamageHandler)Delegate.Combine(health.takeDamageEventHandlers, new Health.OnTakeDamageHandler(TakeDamageEvent));
		}
		initialized = true;
	}

	public override void Start()
	{
		base.Start();
		if (!initialized)
		{
			Initialize();
		}
	}

	public void TakeDamageEvent(AttackInfo attackInfo, Entity attackEntity)
	{
		if (!skipLeafEmit)
		{
			LeafEmitter poolItem = PoolManager.GetPoolItem<LeafEmitter>("FallingLeafEmitter");
			int? num = UnityEngine.Random.Range(2, 4);
			Vector3? position = transform.position + ((!smallTree) ? defaultLeafEmitPos : lowLeafEmitPos);
			LeafEmitter.LeafColor leafColor = this.leafColor;
			poolItem.EmitSingle(num, position, null, null, 0f, null, leafColor);
		}
	}

	public override void Break()
	{
		base.Break();
		PoolManager.GetPoolItem<WoodBreakEffect>().EmitSingle(20, hurtBoxTransform.position + new Vector3(0f, 1.5f, 0f), null, null, 0f, null, WoodBreakEffect.WoodColor.Tree);
		PoolManager.GetPoolItem<WoodBreakEffect>().EmitSingle(10, hurtBoxTransform.position, null, null, 0f, null, WoodBreakEffect.WoodColor.Tree);
		if (!skipLeafEmit)
		{
			LeafEmitter poolItem = PoolManager.GetPoolItem<LeafEmitter>("FallingLeafEmitter");
			int? num = 20;
			Vector3? position = hurtBoxTransform.position + new Vector3(0f, 3f, 0f);
			LeafEmitter.LeafColor leafColor = this.leafColor;
			poolItem.EmitSingle(num, position, null, null, 0f, null, leafColor);
			LeafEmitter poolItem2 = PoolManager.GetPoolItem<LeafEmitter>("FallingLeafBurstEmitter");
			num = 30;
			position = hurtBoxTransform.position + new Vector3(0f, 2f, 0f);
			leafColor = this.leafColor;
			poolItem2.EmitSingle(num, position, null, null, 0f, null, leafColor);
			LeafEmitter poolItem3 = PoolManager.GetPoolItem<LeafEmitter>("FallingLeafBurstEmitter");
			num = 20;
			position = hurtBoxTransform.position + new Vector3(0f, 4f, 0f);
			leafColor = this.leafColor;
			poolItem3.EmitSingle(num, position, null, null, 0f, null, leafColor);
		}
		trunkRenderer.sprite = destroyedVars[treeIndex];
		trunkRenderer.enabled = true;
		floorBaseRenderer.enabled = true;
		trunkRenderer.sortingLayerName = "Wall";
	}
}

using System;
using UnityEngine;

public class VortexTrap : MonoBehaviour
{
	private static GameObject prefab;

	public Attack attack;

	public CircleCollider2D attackCol;

	public ParticleSystem windPartSys;

	public ParticleSystem dustPartSys;

	public float warmupTime = 0.5f;

	private int warmupStopwatchID;

	private bool warmupCompleted;

	public float lifeTime = 3.5f;

	private int lifeStopwatchID;

	private string skillCategory = string.Empty;

	private string skillID = string.Empty;

	private Entity parentEntity;

	public bool alignVacuumToKBVec;

	private bool destroyQueued;

	private bool targetHit;

	private bool warmUpEffectDone;

	private Vector2 spawnOffset = Vector3.up;

	private AudioSource spinAudio;

	private Vector2 currentPos;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/VortexTrap.prefab"));

	private void Start()
	{
		Attack attack = this.attack;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		Attack attack2 = this.attack;
		attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		warmupStopwatchID = ChaosStopwatch.Begin(warmupTime);
		lifeStopwatchID = ChaosStopwatch.Begin(lifeTime);
		currentPos = transform.position;
		PoolManager.GetPoolItem<ParticleEffect>("WindSwirlMed").Emit(1, currentPos);
		ParticleEffect poolItem = PoolManager.GetPoolItem<ParticleEffect>("WindSwirlMed");
		int? particleCount = 1;
		Vector3? position = currentPos;
		Vector3? localEulerAngles = Globals.Vector3AngleDown;
		poolItem.Emit(particleCount, position, null, localEulerAngles);
		PoolManager.GetPoolItem<SectionedTrailEmitter>("WindTrail").Emit(currentPos + spawnOffset * 2.5f, currentPos, -1, emitEveryOther: false, -1f, snapToFit: true, 0.4f);
		PoolManager.GetPoolItem<SectionedTrailEmitter>("WindTrail").Emit(currentPos + spawnOffset * 2.5f, currentPos, -1, emitEveryOther: false, -1f, snapToFit: true, 0.4f);
	}

	private void Update()
	{
		if (destroyQueued)
		{
			return;
		}
		if (ChaosStopwatch.Check(lifeStopwatchID))
		{
			Reset();
			return;
		}
		if (!warmupCompleted)
		{
			currentPos = transform.position;
			if (ChaosStopwatch.Check(warmupStopwatchID))
			{
				PoolManager.GetPoolItem<ParticleEffect>("SpinningAirBurst").Emit(1, currentPos + Vector2.up * 0.25f);
				ParticleEffect poolItem = PoolManager.GetPoolItem<ParticleEffect>("SpinningAirBurst");
				int? particleCount = 1;
				Vector3? position = currentPos + Vector2.up * 0.5f;
				Vector3? localEulerAngles = Globals.Vector3AngleDown;
				poolItem.Emit(particleCount, position, null, localEulerAngles);
				PoolManager.GetPoolItem<ParticleEffect>("SpinningAirBurst").Emit(1, currentPos + Vector2.up * 0.75f);
				ParticleEffect poolItem2 = PoolManager.GetPoolItem<ParticleEffect>("SpinningAirBurst");
				particleCount = 1;
				localEulerAngles = currentPos + Vector2.up;
				position = Globals.Vector3AngleDown;
				poolItem2.Emit(particleCount, localEulerAngles, null, position);
				dustPartSys.Emit(100);
				warmupCompleted = true;
				attackCol.enabled = true;
				windPartSys.Play();
				ParticleEffect poolItem3 = PoolManager.GetPoolItem<ParticleEffect>("WindSwirlMed");
				particleCount = 1;
				position = currentPos;
				localEulerAngles = Globals.GetRotationVector(Vector2.up);
				poolItem3.Emit(particleCount, position, null, localEulerAngles);
			}
			else if (!warmUpEffectDone && ChaosStopwatch.GetTimePercentage(warmupStopwatchID) >= 0.5f)
			{
				warmUpEffectDone = true;
				PoolManager.GetPoolItem<ParticleEffect>("WindSwirlMed").Emit(1, currentPos);
				ParticleEffect poolItem4 = PoolManager.GetPoolItem<ParticleEffect>("WindSwirlMed");
				int? particleCount = 1;
				Vector3? localEulerAngles = currentPos;
				Vector3? position = Globals.Vector3AngleDown;
				poolItem4.Emit(particleCount, localEulerAngles, null, position);
			}
		}
		spinAudio = SoundManager.PlayIfNotPlaying("WindVortexLoop", spinAudio, transform);
	}

	private void OnTargetHit(Entity givenEntity)
	{
		if (!targetHit && !(givenEntity == null) && !(givenEntity is Destructible))
		{
			targetHit = true;
			CreateVacuumShot((givenEntity.transform.position - transform.position).normalized);
			currentPos = transform.position;
			PoolManager.GetPoolItem<ParticleEffect>("WindTwirlSmallEffect").Emit(1, currentPos);
			ParticleEffect poolItem = PoolManager.GetPoolItem<ParticleEffect>("WindTwirlSmallEffect");
			int? particleCount = 1;
			Vector3? position = currentPos;
			Vector3? localEulerAngles = Globals.Vector3AngleDown;
			poolItem.Emit(particleCount, position, null, localEulerAngles);
			Reset();
		}
	}

	private void CreateVacuumShot(Vector2 givenVector)
	{
		if (alignVacuumToKBVec)
		{
			givenVector = attack.knockbackOverwriteVector;
		}
		currentPos = transform.position;
		VacuumShot vacuumShot = (VacuumShot)Projectile.CreateProjectile(parentEntity, VacuumShot.Prefab, currentPos + spawnOffset, Globals.GetRotationQuaternion(givenVector));
		vacuumShot.attackBox.SetAttackInfo(skillCategory, skillID);
		vacuumShot.moveVector = givenVector;
		SoundManager.PlayWithDistAndSPR("VacuumShot", currentPos);
	}

	private void Reset()
	{
		if (!destroyQueued)
		{
			destroyQueued = true;
			windPartSys.Stop();
			windPartSys.Clear();
			dustPartSys.Stop();
			attackCol.enabled = false;
			UnityEngine.Object.Destroy(gameObject, 1f);
			Attack attack = this.attack;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			currentPos = transform.position;
			PoolManager.GetPoolItem<ParticleEffect>("SpinningCircleBurst").Emit(1, currentPos);
			PoolManager.GetPoolItem<ParticleEffect>("SpinningAirBurst").Emit(1, currentPos + Vector2.up * 0.5f);
			ParticleEffect poolItem = PoolManager.GetPoolItem<ParticleEffect>("SpinningAirBurst");
			int? particleCount = 1;
			Vector3? position = currentPos + Vector2.up;
			Vector3? localEulerAngles = Globals.Vector3AngleDown;
			poolItem.Emit(particleCount, position, null, localEulerAngles);
			if (spinAudio != null)
			{
				spinAudio.Stop();
				spinAudio = null;
			}
		}
	}

	public void SetSkillInfo(string givenCategory, string givenID, Entity givenEntity)
	{
		attack.SetAttackInfo(givenCategory, givenID, 3);
		skillCategory = givenCategory;
		skillID = givenID;
		parentEntity = givenEntity;
	}

	private void OnDestroy()
	{
		if (spinAudio != null)
		{
			spinAudio.Stop();
			spinAudio = null;
		}
	}
