# 00 — Глоссарий: единые термины спецификации

Один канонический русский термин на понятие. Все файлы `00`–`30` (включая `05b`, `05c`, `15`, `15b`, `coverage.md`) используют только термины из этого файла. Идентификаторы референса живут исключительно в колонках и строках «Источник»; имена арканов, врагов и реликвий — свои (описательные), не переводы внутренних ID. Ключи схем данных (`overdrive{}`, `od_gain_mult`, `archetype`, `spell_list` и т. п.) остаются английскими: это имена полей, а не термины текста; соответствие — в колонке «Поле данных».

Формат строки: **термин** — определение; *не использовать* — запрещённые синонимы.

using System.Collections.Generic;
using Chaos.AnimatorExtensions;
using Chaos.VectorExtensions;
using UnityEngine;

public class BasicMinion : Entity
{
	public class MinionIdleState(string newName, FSM newFSM, BasicMinion newEnt) : State<BasicMinion>(newName, newFSM, newEnt)
	{
		public string animName = string.Empty;

		public Vector2 parentPosition;

		public override void OnEnter()
		{
			parent.isIdle = true;
			if (animName != string.Empty)
			{
				parent.anim.PlayDirectional(animName);
			}
		}

		public override void Update()
		{
			if (!(parent.parentTrans == null))
			{
				parentPosition = parent.parentTrans.position;
				if (Vector2.Distance(parent.transform.position, parentPosition) > parent.idleDistToParent)
				{
					OnFollow();
				}
				else if (parent.UpdateTargetInfo() != null && parent.CanApproachTarget(parentPosition, parent.closestTargetInfo.position, parent.maxDistToParent + parent.attackRadius))
				{
					OnChase();
				}
			}
		}

		public virtual void OnFollow()
		{
			fsm.ChangeState("FollowParent");
		}

		public virtual void OnChase()
		{
			parent.isIdle = false;
			fsm.ChangeState("MoveToEnemy");
		}
	}

	public class FollowParentState(string newName, FSM newFSM, BasicMinion newEnt) : State<BasicMinion>(newName, newFSM, newEnt)
	{
		public string animName = string.Empty;

		public Vector2 parentPosition;

		public Vector2 endPosition;

		public float endRange;

		public override void OnEnter()
		{
			if (animName != string.Empty)
			{
				parent.anim.PlayDirectional(animName);
			}
			parent.PlayMoveAudio();
		}

		public override void Update()
		{
			if (parent.parentTrans == null)
			{
				fsm.ChangeState(fsm.defaultStateName);
				return;
			}
			parentPosition = parent.parentTrans.position;
			endPosition = Globals.GetLinecastVector(parentPosition, parentPosition + parent.followOffset, parent.lineOfSightLayerMask);
			endRange = ((!parent.isIdle) ? (parent.maxDistToParent * 0.75f) : (parent.idleDistToParent * 0.75f));
			if (!parent.HandleTeleportToPlayer(parentPosition) && parent.MoveToTargetOrFollowPath(parent.transform.position, endPosition, parent.teleportToPlayerRange, endRange, animName))
			{
				parent.movement.MoveToTarget(parentPosition, 0f, 0f, dryRun: false, endMovementOnFinish: false);
				fsm.ChangeState(fsm.defaultStateName);
			}
		}
	}

	public class MoveToEnemyState(string newName, FSM newFSM, BasicMinion newEnt) : State<BasicMinion>(newName, newFSM, newEnt)
	{
		public string animName = string.Empty;

		public Vector2 currentPosition;

		public Vector2 parentPosition;

		public Vector2 targetPosition;

		public bool transitionToAttack;

		public bool moveOnTransition = true;

		public override void OnEnter()
		{
			if (animName != string.Empty)
			{
				parent.anim.PlayDirectional(animName);
			}
			parent.PlayMoveAudio();
		}

		public override void Update()
		{
			if (parent.parentTrans == null)
			{
				fsm.ChangeState(fsm.defaultStateName);
				return;
			}
			currentPosition = parent.transform.position;
			parentPosition = parent.parentTrans.position;
			if (Vector2.Distance(currentPosition, parentPosition) > parent.maxDistToParent + parent.attackRadius || parent.UpdateTargetInfo() == null)
			{
				fsm.ChangeState("FollowParent");
				return;
			}
			targetPosition = parent.closestTargetInfo.position;
			if (parent.MoveToTargetOrFollowPath(currentPosition, targetPosition, parent.maxDistToParent + parent.attackRadius, parent.attackRadius * 0.9f, animName))
			{
				transitionToAttack = Entity.HasLineOfSight(currentPosition, targetPosition, parent.attackRadius, parent.lineOfSightLayerMask);
				fsm.ChangeState((!transitionToAttack) ? "FollowParent" : "Attack");
				if (moveOnTransition && (!transitionToAttack || Vector2.Distance(currentPosition, targetPosition) > parent.attackRadius * 0.9f))
				{
					parent.movement.MoveToTarget(targetPosition, 0f, 0f, dryRun: false, endMovementOnFinish: false);
				}
			}
		}
	}

	public class MinionAttackState(string newName, FSM newFSM, BasicMinion newEnt) : State<BasicMinion>(newName, newFSM, newEnt)
	{
		public string animName = "Attack";

		public bool useDirectionalAnim = true;

		public float atkAnimExecTime = 0.25f;

		public bool attackCompleted;

		public string attackAudioID = "StandardHeavySwing";

		public bool playAudio = true;

		public bool audioPlayed;

		public float currentAnimTime;

		private bool firstFrame;

		public override void OnEnter()
		{
			parent.FaceTarget(parent.closestTargetInfo.hurtBoxTransform.position);
			parent.anim.PlayDirectional((!useDirectionalAnim) ? animName : (animName + parent.facingDirection));
			audioPlayed = !playAudio;
			firstFrame = true;
			attackCompleted = false;
		}

		public override void Update()
		{
			if (firstFrame)
			{
				firstFrame = false;
			}
			else if (!attackCompleted)
			{
				if (parent.anim.AnimPlayed(atkAnimExecTime))
				{
					attackCompleted = true;
					ExecuteAttack();
					if (!audioPlayed)
					{
						audioPlayed = true;
						SoundManager.PlayAudioWithDistance(attackAudioID, parent.transform.position);
					}
				}
			}
			else if (parent.anim.AnimPlayed())
			{
				fsm.ChangeState("MoveToEnemy");
			}
		}

		public virtual void ExecuteAttack()
		{
		}
	}

	public class MinionHurtState : HurtState
	{
		private int hurtStopwatchID;

		private new BasicMinion parent;

		public MinionHurtState(string newName, FSM newFSM, BasicMinion newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
		}

		public override void OnEnter()
		{
			if (parent.isEnemy)
			{
				if (parent.health != null)
				{
					parent.ApplyKnockback(parent.health.lastAttack);
				}
				hurtStopwatchID = ChaosStopwatch.Begin(0.25f * parent.hitStunDurationModifier);
			}
		}

		public override void Update()
		{
			if (!parent.isEnemy || ChaosStopwatch.Check(hurtStopwatchID))
			{
				fsm.ChangeState(fsm.defaultStateName);
			}
		}
	}

	public class MinionDeadState(string newName, FSM newFSM, BasicMinion newEnt) : State<BasicMinion>(newName, newFSM, newEnt)
	{
		public string animName = "Dead";

		public bool destroyOnEnter;

		public string deadAudioID = string.Empty;

		public override void OnEnter()
		{
			parent.anim.Play(animName);
			if (parent.groupList != null)
			{
				parent.groupList.Remove(parent.gameObject);
			}
			if (parent.parentSummonList != null)
			{
				parent.parentSummonList.Remove(parent.gameObject);
			}
			if (parent.useSummonDuration && parent.durationBar != null)
			{
				parent.durationBar.EndCast();
				Object.Destroy(parent.durationBar.gameObject);
			}
			if (parent.healthBar != null)
			{
				parent.healthBar.SetBarVisible(givenStatus: false);
				Object.Destroy(parent.healthBar.gameObject);
			}
			if (parent.destroyOnDeath && destroyOnEnter)
			{
				CallDestroy();
			}
		}

		public override void Update()
		{
			if (!destroyOnEnter && parent.destroyOnDeath && parent.anim.AnimPlayed())
			{
				CallDestroy();
			}
		}

		private void CallDestroy()
		{
			if (deadAudioID != string.Empty)
			{
				SoundManager.PlayWithDistAndSPR(deadAudioID, parent.transform.position);
			}
			if (parent != null && parent.gameObject != null)
			{
				Object.Destroy(parent.gameObject);
			}
		}
	}

	private static Color outlineColor = new Color(0f, 1f, 1f, 0.5f);

	public Transform parentTrans;

	public List<GameObject> parentSummonList;

	public float followRange = 2f;

