	protected string moveAudioID = string.Empty;

	protected ChaosQuickStopwatch moveAudioStopwatch = new ChaosQuickStopwatch(0.75f);

	public bool useSummonDuration = true;

	public float summonDuration = 10f;

	protected int durationStopwatchID;

	public int startingHealth = 50;

	public float idleDistToParent = 5f;

	public float maxDistToParent = 12f;

	protected bool isIdle;

	public float attackRadius = 1f;

	public float teleportToPlayerRange = 14f;

	public float teleportDiff = 3f;

	public bool destroyOnDeath = true;

	public bool useBurst;

	public int burstLevel = 3;

	private float burstRadius = 2.5f;

