	public int animFacingDirections = 2;

	[HideInInspector]
	public CastBar durationBar;

	[HideInInspector]
	public HealthBar healthBar;

	[HideInInspector]
	public TargetInfo closestTargetInfo;

	[HideInInspector]
	public List<GameObject> targetList;

	[HideInInspector]
	public List<GameObject> groupList;

