	public override void Awake()
	{
		disablePreventFallCollider = true;
		base.Awake();
		InitFSM();
		lineOfSightLayerMask = ChaosCollisions.layerAllWallAndObst;
	}

	public virtual void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		fsm.AddState(new MinionIdleState("Idle", fsm, this));
		fsm.AddState(new FollowParentState("FollowParent", fsm, this));
		fsm.AddState(new MoveToEnemyState("MoveToEnemy", fsm, this));
		fsm.AddState(new MinionAttackState("Attack", fsm, this));
		fsm.AddState(new FrozenState("Frozen", fsm, this));
		fsm.AddState(new MinionHurtState("Hurt", fsm, this));
		fsm.AddState(new MinionDeadState("Dead", fsm, this));
		fsm.ChangeState(fsm.defaultStateName);
	}

	public override void Start()
	{
		base.Start();
		SetAffiliation();
		PlaySpawnEffect(transform.position);
		health.healthStat.SetInitialBaseValue(startingHealth);
		if (SummonedEntity.useHealthOverride)
		{
			health.healthStat.AddMod(SummonedEntity.healthOverrideMod);
		}
		if (useSummonDuration)
		{
			healthBar = Globals.ChaosInst<HealthBar>(HealthBar.Prefab);
			healthBar.parentTrans = transform;
			healthBar.parentHealth = health;
			healthBar.SetBarDimensions(0.46f, 0.54f, 0.45f, 0.46f);
			durationStopwatchID = ChaosStopwatch.Begin(summonDuration);
			durationBar = Globals.ChaosInst<CastBar>(CastBar.Prefab);
			durationBar.parentTrans = transform;
			durationBar.SetBarDimensions(0.46f, 0.54f, 0.44f, 0.45f);
			durationBar.StartCast(durationStopwatchID, givenStatus: false);
		}
		if (isEnemy)
		{
			health.ignoreHurtVarStat.RemoveMod(Health.baseIgnoreMod);
			health.healthStat.AddMod(EnemyGlobalStatManager.healthMod);
			movement.moveSpeedStat.AddMod(new NumVarStatMod("EnemyMinion", -0.3f, 10, VarStatModType.Multiplicative));
			if (spriteRenderer != null)
			{
				spriteRenderer.material.SetColor("_OutlineColor", outlineColor);
			}
		}
		if (attack != null)
		{
			attack.SetAttackInfo(skillCategory, skillID, skillLevel, isUltimate);
		}
		followOffset = Globals.GetCirclePositionVector(16, Random.Range(0, 16)) * followRange;
		traversableNodeMap = Pathfinder.connectedNodeMap;
		requestPathTime = Random.Range(0.5f, 1f);
	}

	public virtual void SetAffiliation()
	{
		if (isEnemy)
		{
			targetList = GameController.allies;
			groupList = GameController.enemies;
			hurtBoxCollider.gameObject.name = "EnemyHurtBox";
			hurtBoxCollider.gameObject.layer = LayerMask.NameToLayer("Enemy");
			floorContact.name = "EnemyFloorContact";
		}
		else
		{
			targetList = GameController.enemies;
			groupList = GameController.allies;
			hurtBoxCollider.gameObject.name = "AllyHurtBox";
			hurtBoxCollider.gameObject.layer = LayerMask.NameToLayer("Player");
			floorContact.name = "AllyFloorContact";
		}
		groupList.Add(gameObject);
	}

	public virtual void PlaySpawnEffect(Vector2 givenPosition)
	{
		Player.SpawnAllyPortal(givenPosition, 0.75f);
	}

	public override void Update()
	{
		if (useSummonDuration && ChaosStopwatch.Check(durationStopwatchID) && !fsm.currentStateName.Contains("Dead"))
		{
			DestroyMinion();
		}
		base.Update();
	}

	public override void FixedUpdate()
	{
		base.FixedUpdate();
		fsm.currentState.FixedUpdate();
	}

	public virtual void SetSkillInfo(string givenCategory, string givenID, int givenLevel = 1, bool givenUlt = false)
	{
		skillCategory = givenCategory;
		skillID = givenID;
		skillLevel = givenLevel;
		isUltimate = givenUlt;
	}

	public virtual bool HandleTeleportToPlayer(Vector2 givenPosition, bool forceMove = false)
	{
		if (forceMove || Vector2.Distance(transform.position, givenPosition) > teleportToPlayerRange)
		{
			PlaySpawnEffect(transform.position);
			transform.position = givenPosition;
			Vector2 startPos = givenPosition;
			Vector2 vec = givenPosition;
			float radius = teleportDiff;
			givenPosition = Globals.GetLinecastVector(startPos, vec.Randomize(1f, radius), ChaosCollisions.layerAllWallAndObst);
			rigidbody2D.MovePosition(givenPosition);
			PlaySpawnEffect(givenPosition);
			return true;
		}
		return false;
	}

	public virtual TargetInfo UpdateTargetInfo()
	{
		return closestTargetInfo = Entity.GetClosestTarget(Entity.GetAllTargetsInRange(targetList, parentTrans.position, maxDistToParent + attackRadius, playerTagOnly: false, parentSummonList), transform.position, maxDistToParent * 2.5f, playerTagOnly: false, parentSummonList);
	}

	public virtual void DestroyMinion()
	{
		fsm.QueueChangeState("Dead");
	}

	public bool MoveToTargetOrFollowPath(Vector3 startPos, Vector3 targetPos, float losRange, float moveToRadius = 0f, string moveAnimName = "Run")
	{
		if (Entity.HasLineOfSight(startPos, targetPos, losRange, lineOfSightLayerMask))
		{
			ChaosStopwatch.Stop(requestPathStopwatchID);
			if (moveAnimName != string.Empty)
			{
				PlayAnimOnFaceDirChange(moveAnimName, targetPos, animFacingDirections, appendFacingDirection: false);
			}
			if (movement.MoveToTarget(targetPos, moveToRadius))
			{
				FaceTarget(targetPos, animFacingDirections);
				return true;
			}
			return false;
		}
		if (ChaosStopwatch.Check(requestPathStopwatchID))
		{
			requestPathStopwatchID = ChaosStopwatch.Begin(requestPathTime);
			followingPath = false;
			if (FindAndTraversePath(traversableNodeMap, startPos, targetPos, minNodeDist, moveAnimName, appendFacingDirection: false, animFacingDirections, startNew: true) == -1)
			{
				return true;
			}
			followingPath = true;
			return false;
		}
		if (followingPath && FindAndTraversePath(traversableNodeMap, startPos, targetPos, minNodeDist, moveAnimName, appendFacingDirection: false, animFacingDirections) != 0)
		{
			followingPath = false;
			return true;
		}
		return false;
	}

	public bool CanApproachTarget(Vector3 startPos, Vector3 targetPos, float maxDist)
	{
		return Entity.HasLineOfSight(startPos, targetPos, maxDist, lineOfSightLayerMask) || Pathfinder.GetPath(traversableNodeMap, targetPos, startPos, lineOfSightLayerMask) != null;
	}

	public void PlayMoveAudio()
	{
		if (moveAudioID != string.Empty && !moveAudioStopwatch.IsRunning)
		{
			moveAudioStopwatch.IsRunning = true;
			SoundManager.PlayWithDistAndSPR(moveAudioID, transform.position);
		}
	}
}

using System;
using Chaos.AnimatorExtensions;
using UnityEngine;
public class ChaosClone : MonoBehaviour
{
	public class CloneIdleState : State<ChaosClone>
	{
		private int delayStopwatchID;
		private bool queueDash;
		public CloneIdleState(string newName, FSM newFSM, ChaosClone newClone)
			: base(newName, newFSM, newClone)
		{
		}
		public override void OnEnter()
		{
			parent.PlayAnim("Idle");
			parent.movement.EndMovement();
			queueDash = parent.DashAvailable;
			delayStopwatchID = ((!queueDash) ? (-1) : ChaosStopwatch.Begin(1f + UnityEngine.Random.Range(-0.125f, 0.25f)));
		}
		public override void Update()
		{
			if (ChaosStopwatch.Check(delayStopwatchID))
			{
				if (parent.parentPlayer == null || !queueDash)
				{
					fsm.ChangeState("Dead");
					return;
				}
				parent.dashToParent = true;
				fsm.ChangeState("Dash");
			}
		}
	}
	public class CloneMoveState : State<ChaosClone>
	{
		protected string enterAnimStr = string.Empty;
		private string exitStateName = string.Empty;
		private ChaosQuickStopwatch moveStopwatch = new ChaosQuickStopwatch();
		private NumVarStatMod speedMod = new NumVarStatMod("ChaosClone", 1f, 10, VarStatModType.Override);
		public CloneMoveState(string newName, FSM newFSM, ChaosClone newClone, string givenEnter, string givenExit, float givenTime, float givenSpeed)
			: base(newName, newFSM, newClone)
		{
			enterAnimStr = givenEnter;
			exitStateName = givenExit;
			moveStopwatch.SetDelay(givenTime);
			speedMod.modValue = givenSpeed;
		}
		public override void OnEnter()
		{
			parent.PlayAnim(enterAnimStr);
			parent.movement.moveSpeedStat.AddMod(speedMod);
			moveStopwatch.IsRunning = true;
		}
		public override void FixedUpdate()
		{
			if (moveStopwatch.IsRunning)
			{
				parent.movement.MoveToMoveVector();
			}
			else
			{
				ExitTransition();
			}
		}
		public override void OnExit()
		{
			parent.movement.moveSpeedStat.RemoveMod(speedMod);
			parent.movement.EndMovement();
		}
		public virtual void ExitTransition()
		{
			fsm.ChangeState(exitStateName);
		}
	}
	public class CloneSlideState(string newName, FSM newFSM, ChaosClone newClone) : CloneMoveState(newName, newFSM, newClone, "Slide", "Idle", 0.3f, 10f)
	{
		public string exitStateName = "Dash";
		private bool firstSlide = true;
		public override void OnEnter()
		{
			base.OnEnter();
			if (firstSlide)
			{
				parent.facingDir = parent.initialFacingDir;
				parent.PlayAnim(enterAnimStr, setFacingDir: false);
			}
			SoundManager.PlayWithDistAndSPR("ChaosFade", parent.transform.position);
		}
		public override void ExitTransition()
		{
			if (firstSlide)
			{
				firstSlide = false;
				fsm.ChangeState(exitStateName);
			}
			else
			{
				base.ExitTransition();
			}
		}
	}
	public class CloneDashState : CloneMoveState
	{
		public CloneDashState(string newName, FSM newFSM, ChaosClone newClone)
			: base(newName, newFSM, newClone, "Dash", "Slide", 0.15f, 50f)
		{
		}
		public override void OnEnter()
		{
			parent.CalculateMoveVector();
			parent.dashCounter++;
			parent.SetDashAttackStatus(givenStatus: true);
			ToggleEnemyFloorCollisions(givenStatus: false);
			base.OnEnter();
		}
		public override void OnExit()
		{
			base.OnExit();
			parent.SetDashAttackStatus(givenStatus: false);
			ToggleEnemyFloorCollisions(givenStatus: true);
		}
		private void ToggleEnemyFloorCollisions(bool givenStatus)
		{
			if (parent.floorContact != null)
			{
				parent.floorContact.layer = LayerMask.NameToLayer((!givenStatus) ? "IgnoreEnemyAllyFloorContact" : "AllyFloorContact");
			}
		}
	}
	public class CloneDeadState : State<ChaosClone>
	{
		public CloneDeadState(string newName, FSM newFSM, ChaosClone newClone)
			: base(newName, newFSM, newClone)
		{
		}
		public override void OnEnter()
		{
			Vector2 vector = parent.transform.position + Vector3.up;
			ChaosBurst.Spawn(vector, 3);
			PoolManager.GetPoolItem<AnimEffect>("ChaosPortal").Play(vector, "Depart", 0.3f);
			PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(1, vector);
			SoundManager.PlayWithDistAndSPR("ChaosLightningCrackle", vector);
			if (parent.dashAttack != null)
			{
				parent.dashAttack.Destroy();
			}
			parent.SetEventHandlers(givenStatus: false);
			UnityEngine.Object.Destroy(parent.gameObject);
		}
	}
	private static GameObject _prefab;
	private static int maxDashCount = 3;
	private static Color outlineColor = new Color(0.7f, 0.6f, 0.9f, 0.3f);
	private static Color flashColor = new Color(0.5f, 0.3f, 0.6f, 1f);
	public Animator anim;
	public SpriteRenderer sprite;
	public Movement movement;
	public GameObject floorContact;
	public Transform atkTrans;
	protected FSM fsm;
	private int dashCounter;
	private bool dashToParent;
	protected Player parentPlayer;
	protected string skillCat;
	protected string skillID;
	protected Vector2 moveVector;
	private FacingDirection initialFacingDir;
	private FacingDirection facingDir;
	private ChaosDashAttack dashAttack;
	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/ChaosClone.prefab");
			}
			return _prefab;
		}
	}
	protected bool DashAvailable => fsm != null && fsm.currentStateName != "Dash" && dashCounter < maxDashCount;
	private void Awake()
	{
		sprite.material.SetFloat("_PaletteIndex", 24f);
		sprite.material.SetColor("_OutlineColor", outlineColor);
		sprite.material.SetColor("_FlashColor", flashColor);
		sprite.material.SetFloat("_FlashAmount", 0.65f);
	}
	public void Initialize(Player givenPlayer, string givenID, Vector2 givenVector, FacingDirection givenInitialFacingDir)
	{
		parentPlayer = givenPlayer;
		skillCat = givenPlayer.skillCategory;
		skillID = givenID;
		moveVector = givenVector;
		initialFacingDir = givenInitialFacingDir;
		movement.moveVector = givenVector;
		SetEventHandlers(givenStatus: true);
	}
	protected virtual void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		fsm.AddState(new CloneIdleState("Idle", fsm, this));
		fsm.AddState(new CloneDashState("Dash", fsm, this));
		fsm.AddState(new CloneSlideState("Slide", fsm, this));
		fsm.AddState(new CloneDeadState("Dead", fsm, this));
		fsm.ChangeState("Slide");
	}
	protected virtual void Start()
	{
		InitFSM();
		PoolManager.GetPoolItem<AnimEffect>("ChaosPortal").Play(atkTrans.position, "Depart");
	}
	private void Update()
	{
		if (fsm != null)
		{
			fsm.currentState.Update();
		}
	}
	private void FixedUpdate()
	{
		if (fsm != null)
		{
			fsm.currentState.FixedUpdate();
		}
	}
	protected virtual void SetEventHandlers(bool givenStatus)
	{
		if (!(parentPlayer == null))
		{
			Player player = parentPlayer;
			player.skillExecEventHandlers = (Player.SkillEventHandler)Delegate.Remove(player.skillExecEventHandlers, new Player.SkillEventHandler(OnParentDash));
			if (givenStatus)
			{
				Player player2 = parentPlayer;
				player2.skillExecEventHandlers = (Player.SkillEventHandler)Delegate.Combine(player2.skillExecEventHandlers, new Player.SkillEventHandler(OnParentDash));
			}
		}
	}
	protected void OnParentDash(Player.SkillState givenSkill)
	{
		if (givenSkill != null && givenSkill.isDash && DashAvailable)
		{
			dashToParent = false;
			fsm.ChangeState("Dash");
		}
	}
	protected void PlayAnim(string givenName, bool setFacingDir = true, float givenAnimTime = 0f)
	{
		if (setFacingDir)
		{
			facingDir = Globals.GetPrimaryDirection(moveVector);
		}
		anim.PlayDirectional(givenName + facingDir, -1, givenAnimTime);
		transform.localScale = ((facingDir != FacingDirection.Left) ? Vector3.one : Globals.ScaleVecFlipX);
	}
	protected void CalculateMoveVector()
	{
		if (!(parentPlayer == null))
		{
			if (dashToParent)
			{
				moveVector = (parentPlayer.transform.position - transform.position).normalized;
			}
			else
			{
				moveVector = (parentPlayer.transform.position + (Vector3)parentPlayer.movement.dashVector * 2.5f - transform.position).normalized;
			}
			movement.moveVector = moveVector;
		}
	}
	protected void SetDashAttackStatus(bool givenStatus)
	{
		if (givenStatus)
		{
			if (dashAttack == null)
			{
				dashAttack = Globals.ChaosInst<ChaosDashAttack>(ChaosDashAttack.Prefab, null, atkTrans.position, Globals.GetRotationQuaternion(moveVector));
				dashAttack.followTrans = atkTrans;
				dashAttack.attack.SetAttackInfo(skillCat, skillID, 2);
			}
			dashAttack.attack.knockbackOverwriteVector = moveVector;
			dashAttack.transform.localEulerAngles = Globals.GetRotationVector(moveVector);
			SoundManager.PlayWithDistAndSPR("ChaosDash", atkTrans.position);
		}
		if (dashAttack != null)
		{
			dashAttack.gameObject.SetActive(givenStatus);
		}
	}
	private void OnDestroy()
	{
		SetEventHandlers(givenStatus: false);
	}
}
