		private static string endAnimStr = "Forehand";
		private Vector2 lungeVec;
		private Vector3 holdOffset;
		private ChaosLunge currentCL;
		private int lungeCounter;
		private bool dashCompleted;
		private bool delayCompleted;
		private ChaosQuickStopwatch delayStopwatch = new ChaosQuickStopwatch(0.125f);
		public override void OnEnter()
		{
			lungeVec = parent.dashVecArray[lungeCounter];
			parent.moveVector = lungeVec;
			parent.movement.moveVector = lungeVec;
			parent.movement.dashVector = lungeVec;
			holdOffset = lungeVec * 1.5f;
			parent.PlayAnim(startAnimStr, setFacingDir: true, 0.3f);
			currentCL = parent.CreateChaosLunge();
			dashCompleted = false;
			delayCompleted = false;
			ToggleEnemyFloorCollisions(givenStatus: false);
		}
		public override void Update()
		{
			if (dashCompleted && !delayStopwatch.IsRunning)
			{
				lungeCounter++;
				if (lungeCounter < parent.maxLungeCount)
				{
					fsm.ChangeState(name, allowSelfTransition: true);
					return;
				}
				if (delayCompleted)
				{
					fsm.ChangeState("Dead");
					return;
				}
				delayCompleted = true;
				delayStopwatch.SetDelay(0.25f, stopCurrent: false, autoStart: true);
			}
		}
		public override void FixedUpdate()
		{
			if (dashCompleted)
			{
				return;
			}
			if (parent.movement.DashToTarget())
			{
				dashCompleted = true;
				parent.movement.EndMovement();
				parent.PlayAnim(endAnimStr, setFacingDir: false, 0.3f);
				parent.movement.MoveToMoveVector(8f);
				delayStopwatch.IsRunning = true;
				if (currentCL != null)
				{
					currentCL.rigidbody2D.velocity = parent.moveVector * 8f;
				}
			}
			else if (currentCL != null)
			{
				currentCL.transform.position = parent.atkTrans.position + holdOffset;
			}
		}
		public override void OnExit()
		{
			ToggleEnemyFloorCollisions(givenStatus: true);
		}
		private void ToggleEnemyFloorCollisions(bool givenStatus)
		{
			if (parent.floorContact != null)
			{
				parent.floorContact.layer = LayerMask.NameToLayer((!givenStatus) ? "IgnoreEnemyAllyFloorContact" : "AllyFloorContact");
			}
		}
	}
