	public class CloneHadoState : State<ChaosDropClone>
	{
		private static string foreAnimStr = "Forehand";
		private static string backAnimStr = "Backhand";
		private int atkStopwatchID;
		private bool atkFlip;
		private int exitStopwatchID;
		private bool exitQueued;
		public CloneHadoState(string newName, FSM newFSM, ChaosDropClone newClone)
			: base(newName, newFSM, newClone)
		{
		}
		public override void OnEnter()
		{
			parent.PlayAnim("PBAoE", setFacingDir: true, 0.3f);
			atkStopwatchID = ChaosStopwatch.Begin(0.1f, useInterval: true, 0.125f, 5);
		}
		public override void FixedUpdate()
		{
			if (exitQueued)
			{
				if (ChaosStopwatch.Check(exitStopwatchID))
				{
					fsm.ChangeState("Drop");
				}
				return;
			}
			switch (ChaosStopwatch.CheckInterval(atkStopwatchID))
			{
			case StopwatchState.Ready:
				atkFlip = !atkFlip;
				parent.PlayAnim((!atkFlip) ? foreAnimStr : backAnimStr, setFacingDir: false, 0.3f);
				parent.CreateChaosHado();
				break;
			case StopwatchState.Done:
				exitStopwatchID = ChaosStopwatch.Begin(Random.Range(0.1f, 0.25f));
				exitQueued = true;
				break;
			}
		}
	}
	public class CloneDropState : State<ChaosDropClone>
	{
		private Vector2 currentPos;
		private bool isFaceRight;
		private int delayStopwatchID;
		private bool delayCompleted;
		private int shotStopwatchID;
		private bool shotCompleted;
		private int dropStopwatchID;
		private bool dropCompleted;
		private float dropLerpValue;
		private Vector2 dropStartPos;
		public CloneDropState(string newName, FSM newFSM, ChaosDropClone newClone)
			: base(newName, newFSM, newClone)
		{
		}
		public override void OnEnter()
		{
			delayStopwatchID = ChaosStopwatch.Begin((!parent.isClone) ? 0.125f : Random.Range(0.15f, 0.25f));
			delayCompleted = false;
			currentPos = parent.atkTrans.position;
			ToggleVisuals(givenStatus: false);
			parent.sprite.sortingLayerName = "UI";
			PoolManager.GetPoolItem<AnimEffect>("ChaosPortal").Play(currentPos, "Depart", 0.2f);
			ChaosBurst.Spawn(currentPos, 3);
			SoundManager.PlayWithDistAndSPR("Teleport", currentPos);
			isFaceRight = Globals.RandBool;
		}
		public override void FixedUpdate()
		{
			if (!delayCompleted)
			{
				if (ChaosStopwatch.Check(delayStopwatchID))
				{
					delayCompleted = true;
					parent.transform.position = parent.dropPos;
					parent.sprite.transform.position = parent.dropPos + Vector2.up * 4f;
					if (parent.forceDrop)
					{
						ToggleVisuals(givenStatus: true);
						PlaySlamAnim();
						parent.CreateChaosDrop();
						shotStopwatchID = ChaosStopwatch.Begin(0.125f, useInterval: true, 0.125f, 4);
						shotCompleted = false;
					}
					else
					{
						InitCrashDown();
					}
					currentPos = parent.sprite.transform.position + Vector3.up;
					AnimEffect poolItem = PoolManager.GetPoolItem<AnimEffect>("ChaosPortal");
					Vector3 position = currentPos;
					string animName = "Spawn";
					float normalizedTime = 0.3f;
					Vector3? localEulerAngles = Globals.Vector3Angle90CW;
					poolItem.Play(position, animName, normalizedTime, default, 1f, 1f, localEulerAngles);
					ChaosBurst.Spawn(currentPos, 3);
				}
			}
			else if (!shotCompleted)
			{
				switch (ChaosStopwatch.CheckInterval(shotStopwatchID))
				{
				case StopwatchState.Ready:
					PlaySlamAnim();
					parent.CreateChaosDrop();
					break;
				case StopwatchState.Done:
					InitCrashDown();
					break;
				}
			}
			else if (!dropCompleted)
			{
				dropLerpValue = ChaosStopwatch.GetTimePercentage(dropStopwatchID);
				parent.sprite.transform.position = Vector2.Lerp(dropStartPos, parent.dropPos, dropLerpValue);
				if (dropLerpValue >= 1f)
				{
					dropCompleted = true;
					parent.CreateChaosPillar();
					fsm.ChangeState("Dead");
				}
			}
		}
		private void InitCrashDown()
		{
			shotCompleted = true;
			dropStartPos = parent.dropPos + Vector2.up * 4.5f;
			parent.sprite.transform.position = dropStartPos;
			dropStopwatchID = ChaosStopwatch.Begin(0.18f);
			dropCompleted = false;
			parent.anim.Play((!(parent.atkVector.y > 0f)) ? "FallDown" : "FallUp", -1, 0f);
			ToggleVisuals(givenStatus: true);
		}
		private void PlaySlamAnim()
		{
			isFaceRight = !isFaceRight;
			parent.anim.Play((!(parent.atkVector.y > 0f)) ? "GroundSlamDown" : "GroundSlamUp", -1, 0.3f);
			parent.transform.localScale = ((!isFaceRight) ? Globals.ScaleVecFlipX : Vector3.one);
		}
		private void ToggleVisuals(bool givenStatus)
		{
			parent.sprite.gameObject.SetActive(givenStatus);
			parent.shadow.gameObject.SetActive(givenStatus);
		}
	}
