public class EarthMinion : BasicMinion
{
	public class EarthMinionAttackState : State<EarthMinion>
	{
		private EarthExplosion currentEX;
		private int windStopwatchID;
		private int exitStopwatchID;
		private float exitLerpValue;
		private Vector2 targetPos;
		private Transform targetTrans;
		private bool windupComplete;
		private bool fallStarted;
		private bool formEffectPlayed;
		private bool recoverAnimPlayed;
		private bool empDoubleUp;
		private bool toggleDuration;
		public EarthMinionAttackState(string newName, FSM newFSM, EarthMinion newEnt)
			: base(newName, newFSM, newEnt)
		{
		}
		public override void OnEnter()
		{
			windStopwatchID = ChaosStopwatch.Begin(parent.atkWindupTime);
			windupComplete = false;
			fallStarted = false;
			formEffectPlayed = false;
			recoverAnimPlayed = false;
			empDoubleUp = false;
			ToggleObjects(givenStatus: true);
			targetTrans = ((parent.closestTargetInfo == null) ? parent.transform : parent.closestTargetInfo.transform);
			toggleDuration = parent.useSummonDuration;
			ThrownItem thrownItem = parent.thrownItem;
			thrownItem.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Remove(thrownItem.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(HandleLanding));
			ThrownItem thrownItem2 = parent.thrownItem;
			thrownItem2.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Combine(thrownItem2.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(HandleLanding));
		}
		private void SetThrowVars(bool isSecondThrow = false)
		{
			parent.thrownItem.throwHeight = parent.throwHeight;
			if (isSecondThrow)
			{
				parent.thrownItem.baseFlightTime = parent.baseFlightTime * 0.15f;
				parent.thrownItem.isFallingThreshold = 0f;
				parent.thrownItem.spriteStartPosition = parent.spriteRenderer.transform.localPosition;
			}
			else
			{
				parent.thrownItem.baseFlightTime = parent.baseFlightTime;
				parent.thrownItem.isFallingThreshold = 0.5f;
			}
			ToggleObjects(givenStatus: false);
		}
		public override void Update()
		{
			if (!windupComplete)
			{
				if (ChaosStopwatch.Check(windStopwatchID))
				{
					windupComplete = true;
					exitStopwatchID = ChaosStopwatch.Begin(parent.atkWinddownTime);
					SetThrowVars();
					targetPos = UnityEngine.Random.insideUnitCircle + (Vector2)((!(targetTrans == null)) ? targetTrans.position : parent.transform.position);
					parent.thrownItem.ThrowToTargetVector(targetPos + (targetPos - (Vector2)parent.transform.position));
					parent.SetSortingLayer("UI");
					if (toggleDuration)
					{
						parent.useSummonDuration = false;
					}
				}
				return;
			}
			exitLerpValue = ChaosStopwatch.GetTimePercentage(exitStopwatchID);
			if (exitLerpValue >= 1f)
			{
				fsm.ChangeState(fsm.defaultStateName);
				return;
			}
			if (!recoverAnimPlayed && exitLerpValue >= 0.65f)
			{
				recoverAnimPlayed = true;
				parent.anim.Play("Recover", -1, 0f);
			}
			else if (!fallStarted && parent.thrownItem.isFalling)
			{
				fallStarted = true;
				SetThrowVars(isSecondThrow: true);
				parent.thrownItem.ThrowToTargetVector(targetPos);
			}
			if (!fallStarted && !formEffectPlayed && parent.thrownItem.PercentComplete >= 0.33f)
			{
				formEffectPlayed = true;
				parent.anim.Play("Form", -1, 0f);
				if (!(parent.spriteRenderer == null))
				{
					ParticleEffect poolItem = PoolManager.GetPoolItem<ParticleEffect>("RockFormEffect");
					poolItem.reqFollowTrans = true;
					int? particleCount = 5;
					Vector3? position = parent.spriteRenderer.transform.position;
					ParticleSystemOverride smallFormEffect = RockDebrisEmitter.SmallFormEffect;
					Transform transform = parent.spriteRenderer.transform;
					poolItem.Emit(particleCount, position, smallFormEffect, null, 0f, null, transform);
				}
			}
		}
		public override void OnExit()
		{
			if (toggleDuration)
			{
				parent.useSummonDuration = true;
			}
			parent.attackCollider.enabled = false;
			ToggleObjects(givenStatus: true);
			ThrownItem thrownItem = parent.thrownItem;
			thrownItem.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Remove(thrownItem.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(HandleLanding));
		}
		private void HandleLanding()
		{
			if (toggleDuration)
			{
				parent.useSummonDuration = true;
			}
			parent.SetSortingLayer();
			parent.anim.Play("Land", -1, 0f);
			Vector2 vector = parent.transform.position;
			currentEX = Globals.ChaosInst<EarthExplosion>(EarthExplosion.Prefab, null, vector);
			currentEX.attackBox.SetAttackInfo(parent.skillCategory, parent.skillID, (!empDoubleUp) ? 1 : 2);
			currentEX.attackBox.collider.enabled = true;
			currentEX.warmUpTime = 0f;
			currentEX.waveCount = 0;
			currentEX.spikeCount = 0;
			currentEX.spawnRange = 1.75f;
			currentEX.attackRadius = 2.5f;
			currentEX.emitCountOverride = 4;
			currentEX.emitRadiusOverride = 1.75f;
			currentEX.showCastingCircle = false;
			SoundManager.PlayAudioWithDistance("EarthExplosion", vector);
			PoolManager.GetPoolItem<ParticleEffect>("FloorCrater").Emit(1, vector);
			if (parent.isEmpowered && !empDoubleUp)
			{
				fsm.ChangeState(name, allowSelfTransition: true);
				empDoubleUp = true;
			}
			ToggleObjects(givenStatus: true);
		}
		private void ToggleObjects(bool givenStatus)
		{
			parent.hurtBoxCollider.enabled = givenStatus;
			parent.floorCollider.enabled = givenStatus;
		}
	}
