		{
			if (!(givenTrans == null))
			{
				if (!jumpCompleted && homing && Vector2.SqrMagnitude(parent.transform.position - givenTrans.position) < parent.jumpRangeSq)
				{
					jumpCompleted = true;
					parent.thrownItem.throwHeight = parent.jumpHeight;
					parent.thrownItem.baseFlightTime = parent.jumpTime;
					parent.thrownItem.ThrowToTargetVector(givenTrans.position);
					SetColliderStatus(givenStatus: false);
					parent.Reset();
				}
				else
				{
					base.HandleMovement(givenTrans);
				}
			}
		}
