using System.Collections.Generic;
using Chaos.AnimatorExtensions;
using UnityEngine;
public class PhantomKnight : Entity
{
	private static GameObject prefab;
	public Entity targetEntity;
	private bool moveDone;
	private bool frameSkipped;
	private bool dashStarted;
	private int hitCount = 3;
	public float targetRange = 12f;
	public string skillID = string.Empty;
	public int skillLevel;
	public bool isUltimate;
	[HideInInspector]
	public List<GameObject> playerSummonsList;
	[HideInInspector]
	public GameObject parentObj;
	private NumVarStatMod finalAtkMoveSpeedMod;
	private NumVarStatMod firstAtkMoveSpeedMod;
	private ChaosQuickStopwatch failSafeTimer;
	private float failSafeTime = 2f;
	private bool destroyQueued;
	private ChaosQuickStopwatch destroyStopwatch = new ChaosQuickStopwatch(0.35f);
	public float chargeAnimThreshold = 1f;
	public float chargeAnimStartTime = 0.25f;
	private float dashAnimThreshold = 0.75f;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Effects/PhantomKnight.prefab"));
	private Vector3 BodyPos => transform.position + Vector3.up;
	public override void Awake()
	{
		disablePreventFallCollider = true;
		finalAtkMoveSpeedMod = new NumVarStatMod("PhantomKnightFinalAtkMoveSpeedMod", 50f, 10, VarStatModType.Override);
		firstAtkMoveSpeedMod = new NumVarStatMod("PhantomKnightFirstAtkMoveSpeedMod", 5f, 10, VarStatModType.Override);
		failSafeTimer = new ChaosQuickStopwatch(failSafeTime);
		base.Awake();
	}
	public override void Start()
	{
		base.Start();
		SetElementParams(skillLevel - 1);
		spriteRenderer.material.SetColor("_OutlineColor", new Color(1f, 1f, 1f, 0.2f));
		movement.moveSpeedStat.SetInitialBaseValue(18f);
		anim.Play("ChargeAlt", -1, chargeAnimStartTime);
		PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(4, BodyPos);
	}
	private void SetElementParams(int givenIndex)
	{
		switch (givenIndex)
		{
		case 0:
			spriteRenderer.color = new Color(1f, 0.4f, 0f, 0.4f);
			hitCount = 3;
			dashAnimThreshold = 1.25f;
			break;
		case 1:
			spriteRenderer.color = new Color(1f, 1f, 1f, 0.4f);
			hitCount = 6;
			dashAnimThreshold = 0.5f;
			break;
		case 2:
			spriteRenderer.color = new Color(0.4f, 0.4f, 0.2f, 0.4f);
			hitCount = 3;
			dashAnimThreshold = 1.375f;
			break;
		case 3:
			spriteRenderer.color = new Color(1f, 1f, 0f, 0.4f);
			hitCount = 4;
			dashAnimThreshold = 0.625f;
			break;
		case 4:
			spriteRenderer.color = new Color(0f, 1f, 1f, 0.4f);
			hitCount = 5;
			dashAnimThreshold = 0.7f;
			break;
		default:
			hitCount = 4;
			dashAnimThreshold = 0.625f;
			break;
		}
	}
	public override void Update()
	{
		if (destroyQueued)
		{
			if (!destroyStopwatch.IsRunning && gameObject != null)
			{
				Object.Destroy(gameObject);
				PoolManager.GetPoolItem<ParticleEffect>("ChaosChargeEffect").Emit(3, BodyPos, ParticleEffectOverrides.StartLifeTime0p25);
				AnimEffect poolItem = PoolManager.GetPoolItem<AnimEffect>("ChaosPortal");
				Vector3 bodyPos = BodyPos;
				string animName = "Depart";
				Vector3? localEulerAngles = new Vector3(0f, 0f, Random.Range(0f, 360f));
				poolItem.Play(bodyPos, animName, 0f, default, 1f, 1f, localEulerAngles);
				animName = "EnemyDead";
				Vector2? soundOrigin = BodyPos;
				float overridePitch = Random.Range(1.1f, 1.2f);
				SoundManager.PlayAudioWithDistance(animName, soundOrigin, null, 24f, -1f, overridePitch);
			}
			return;
		}
		base.Update();
		if (parentObj == null)
		{
			DestroyKnight();
			return;
		}
		if (!dashStarted)
		{
			if (!anim.AnimPlayed(chargeAnimThreshold))
			{
				return;
			}
			if (!frameSkipped)
			{
				frameSkipped = true;
				return;
			}
			dashStarted = true;
			failSafeTimer.IsRunning = true;
			AquireTarget();
			if (targetEntity == null)
			{
				DestroyKnight();
				return;
			}
			anim.Play("Dash", -1, 0f);
			frameSkipped = false;
			PoolManager.GetPoolItem<DashAirBurst>().Burst(BodyPos, (targetEntity.transform.position - transform.position).normalized, useOffset: false);
			string animName = "StandardDash";
			Vector2? soundOrigin = transform.position;
			float overridePitch = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(animName, soundOrigin, null, 24f, -1f, overridePitch);
		}
		else if (targetEntity == null)
		{
			AquireTarget();
			if (targetEntity == null)
			{
				DestroyKnight();
				return;
			}
		}
		if (!moveDone)
		{
			return;
		}
		if (!frameSkipped)
		{
			frameSkipped = true;
		}
		else if (anim.AnimPlayed(dashAnimThreshold))
		{
			movement.moveSpeedStat.RemoveMod(firstAtkMoveSpeedMod);
			movement.moveSpeedStat.RemoveMod(finalAtkMoveSpeedMod);
			hitCount--;
			if (hitCount <= 0)
			{
				DestroyKnight();
			}
			else
			{
				Reset();
			}
		}
	}
	private void Reset()
	{
		dashStarted = false;
		frameSkipped = false;
		moveDone = false;
	}
	private void DestroyKnight()
	{
		if (!destroyQueued)
		{
			destroyQueued = true;
			destroyStopwatch.IsRunning = true;
			anim.Play("Charge", -1, 0.4f);
			movement.EndMovement();
			PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(5, BodyPos);
			string audioID = "ChaosLightningCrackle";
			Vector2? soundOrigin = transform.position;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
		}
	}
	public void AquireTarget()
	{
		if (!(targetEntity != null))
		{
			TargetInfo closestTarget = Entity.GetClosestTarget(GameController.enemies, (!(parentObj == null)) ? parentObj.transform.position : transform.position, targetRange, playerTagOnly: false, playerSummonsList, parentObj, requireLOS: true, ChaosCollisions.layerAllWallAndObst);
			if (closestTarget != null)
			{
				targetEntity = closestTarget.entity;
			}
		}
	}
	public override void FixedUpdate()
	{
		if (!(targetEntity == null) && dashStarted && !moveDone)
		{
			FaceTarget(targetEntity.transform.position, 2);
			if (movement.MoveToTarget(targetEntity.transform, 2.5f))
			{
				FaceTarget(targetEntity.transform.position);
				moveDone = true;
				movement.EndMovement();
				anim.PlayDirectional("Attack" + facingDirection, -1, 0.45f);
				attack.SetAttackInfo(skillCategory, skillID, skillLevel, isUltimate);
				movement.moveSpeedStat.AddMod(finalAtkMoveSpeedMod);
				movement.MoveToMoveVector();
			}
			else if (!failSafeTimer.IsRunning)
			{
				DestroyKnight();
			}
		}
	}
}
using System.Collections.Generic;
using UnityEngine;
public class PhantomOrb : Entity
{
