	public override void Start()
	{
		anim.Play("ChargeWindup", -1, 0f);
		originAngle = spriteRenderer.transform.localEulerAngles.z;
		currentPos = bodyTrans.position;
		ChaosBurst.Spawn(currentPos, 5);
		SoundManager.PlayWithDistAndSPR("ChaosFormShort", currentPos);
		spriteRenderer.material.SetColor("_OutlineColor", new Color(1f, 1f, 1f, 0.2f));
		lifeStopwatchID = ChaosStopwatch.Begin(8f);
	}
	public override void Update()
	{
		if (!destroyQueued && ChaosStopwatch.Check(lifeStopwatchID))
		{
			DestroyOrb();
		}
		else if (!atkCompleted)
		{
			if (!roteCompleted)
			{
				windLerpValue = ChaosStopwatch.GetTimePercentage(windupStopwatchID);
				anim.Play("ChargeWindup", -1, windLerpValue);
				spriteRenderer.transform.localEulerAngles = new Vector3(0f, 0f, Mathf.Lerp(originAngle, targetAngle, windLerpValue));
				roteCompleted = windLerpValue >= 1f;
			}
			else if (!atkStarted)
			{
				atkStarted = true;
				attack.collider.enabled = true;
				SoundManager.PlayWithDistAndSPR("ChaosFormShort", bodyTrans.position);
			}
		}
		else if (destroyQueued && ChaosStopwatch.Check(destroyStopwatchID))
		{
			DestroyOrb();
		}
	}
	public override void FixedUpdate()
	{
		if (atkStarted && !atkCompleted && movement.DashToTarget())
		{
			atkCompleted = true;
			anim.Play("ChargeWinddown", -1, 0f);
			movement.EndMovement();
			movement.MoveToMoveVector(10f);
			attack.collider.enabled = false;
			if (destroyQueued)
			{
				destroyStopwatchID = ChaosStopwatch.Begin(0.4f);
			}
		}
	}
	public void DestroyOrb()
	{
		if (!(gameObject == null))
		{
			currentPos = bodyTrans.position;
			ChaosBurst.Spawn(currentPos, 5);
			PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(3, currentPos);
			SoundManager.PlayWithDistAndSPR("ChaosLightningCrackle", currentPos);
			string audioID = "TornadoEnd";
			Vector2? soundOrigin = currentPos;
			float overridePitch = Random.Range(1.1f, 1.2f);
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, 0.15f, overridePitch);
			Object.Destroy(gameObject);
		}
	}
	public void Attack(bool givenDestroy = false)
	{
		if (!FindTarget())
		{
			DestroyOrb();
			return;
		}
		atkStarted = false;
		atkCompleted = false;
		roteCompleted = false;
		destroyQueued = givenDestroy;
		movement.EndMovement();
		movement.moveVector = atkVector;
		movement.dashVector = atkVector;
		attack.knockbackOverwriteVector = atkVector;
		originAngle = spriteRenderer.transform.localEulerAngles.z;
		targetAngle = Globals.GetRotationVector(atkVector).z;
		windupStopwatchID = ChaosStopwatch.Begin(Random.Range(0.15f, 0.25f));
		string audioID = "LaserOrbWindup";
		Vector2? soundOrigin = bodyTrans.position;
		float standardPitchRange = SoundManager.StandardPitchRange;
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, 0.1f, standardPitchRange);
	}
	private bool FindTarget()
	{
		targetList = Entity.GetAllTargetsInRange(GameController.enemies, transform.position, 9f, playerTagOnly: false, playerSummonsList, parentObj, requireLOS: true, ChaosCollisions.layerAllWallAndObst);
		if (targetList != null && targetList.Count > 0)
		{
			targetInfo = Entity.GetTargetInfoFromObject(targetList[Random.Range(0, targetList.Count)]);
			targetList.Clear();
			if (targetInfo != null)
			{
				atkVector = (targetInfo.position - transform.position).normalized;
				return true;
			}
		}
		return false;
	}
}
using System;
using UnityEngine;
public class PhantomRogue : Entity
{
	private static GameObject prefab;
	public Transform bodyTrans;
	public Attack atkCircle;
	public Attack atkBox;
	private Vector2 initDashVec;
	private Vector2 currentPos;
	private int delayStopwatchID;
	private bool dashCompleted;
	private bool atkStarted;
	private bool atkCompleted;
	private bool animPlayed;
	private bool destroyQueued;
	private bool targetHit;
	private Entity targetEntity;
	private Vector2 atkVector;
	private Vector3 roteVector;
	private ChaosQuickStopwatch destroyStopwatch = new ChaosQuickStopwatch(0.25f);
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Effects/PhantomRogue.prefab"));
	public override void Awake()
	{
		disablePreventFallCollider = true;
		base.Awake();
	}
	public override void Start()
	{
		base.Start();
		StartDash(initDashVec);
		Attack attack = atkCircle;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		Attack attack2 = atkCircle;
		attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		atkCircle.knockbackOverwriteVector = initDashVec;
		atkCircle.collider.enabled = true;
		spriteRenderer.material.SetColor("_OutlineColor", new Color(1f, 1f, 1f, 0.2f));
		currentPos = bodyTrans.position;
		PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(2, currentPos);
		PoolManager.GetPoolItem<AnimEffect>("ChaosPortal").Play(currentPos, "Spawn");
		SoundManager.PlayWithDistAndSPR("StandardDash", currentPos);
	}
	public override void Update()
	{
		if (destroyQueued)
		{
			if (!destroyStopwatch.IsRunning)
			{
				DestroyRogue();
			}
			else if (!animPlayed && destroyStopwatch.TimePercentage >= 0.6f)
			{
				animPlayed = true;
				anim.Play("StealthNoColorChange", -1, 0f);
			}
		}
		else
		{
			if (!dashCompleted)
			{
				return;
			}
			SetXScale();
			if (!ChaosStopwatch.Check(delayStopwatchID))
			{
				return;
			}
			if (!atkStarted)
			{
				atkStarted = true;
				if (!targetHit)
				{
					anim.Play("Crouch", -1, 1f);
					QueueDestroy();
					return;
				}
				if (targetEntity.hurtBoxTransform != null)
				{
					atkVector = (targetEntity.hurtBoxTransform.position - atkBox.transform.position).normalized;
				}
				FaceTarget(transform.position + (Vector3)atkVector, 2);
				SetXScale();
				anim.Play("Attack", -1, 0.4f);
				atkBox.knockbackOverwriteVector = atkVector;
				roteVector = Globals.GetRotationVector(atkVector);
				if (!isFacingRight)
				{
					roteVector.z *= -1f;
				}
				atkBox.transform.localEulerAngles = roteVector;
				delayStopwatchID = ChaosStopwatch.Begin(0.1f);
				string audioID = "RogueAttack";
				Vector2? soundOrigin = transform.position;
				float overridePitch = UnityEngine.Random.Range(1f, 1.1f);
				SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
			}
			else if (!atkCompleted)
			{
				atkCompleted = true;
				atkStarted = false;
				atkBox.ChangeAttackInfoLevel(3);
			}
			else
			{
				animPlayed = true;
				movement.dashSpeedStat.SetInitialBaseValue(10f);
				movement.dashDurationStat.SetInitialBaseValue(0.2f);
				StartDash(-atkVector, isReverse: true);
				destroyStopwatch.SetDelay(0.15f);
				QueueDestroy();
			}
		}
	}
	public override void FixedUpdate()
	{
		if (dashCompleted || !movement.DashToTarget())
		{
			return;
		}
		dashCompleted = true;
		if (destroyQueued)
		{
			DestroyRogue();
			return;
		}
		anim.Play("Crouch", -1, 1f);
		atkCircle.collider.enabled = false;
		Attack attack = atkCircle;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		if (!targetHit)
		{
			movement.moveVector = initDashVec;
			movement.MoveToMoveVector();
		}
	}
	private void StartDash(Vector3 givenVec, bool isReverse = false)
	{
		FaceTarget(transform.position + ((!isReverse) ? givenVec : (-givenVec)), 2);
		SetXScale();
		anim.Play((!isReverse) ? "Dash" : "BackDash", -1, 0f);
		movement.dashVector = givenVec;
		dashCompleted = false;
		delayStopwatchID = ChaosStopwatch.Begin(0.15f);
	}
	private void OnTargetHit(Entity entity)
	{
		if (!targetHit && !(entity == null) && !(entity is Destructible))
		{
			targetHit = true;
			targetEntity = entity;
			movement.EndMovement();
			Attack attack = atkCircle;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			movement.dashSpeedStat.SetInitialBaseValue(27f);
			StartDash((initDashVec * 2f + UnityEngine.Random.insideUnitCircle).normalized, isReverse: true);
		}
	}
	private void QueueDestroy()
	{
		if (!destroyQueued)
		{
			destroyQueued = true;
			destroyStopwatch.IsRunning = true;
			Attack attack = atkCircle;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		}
	}
	private void DestroyRogue()
	{
		if (!(gameObject == null))
		{
			currentPos = bodyTrans.position;
			PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(2, currentPos);
			PoolManager.GetPoolItem<ParticleEffect>("ChaosChargeEffect").Emit(1, currentPos, ParticleEffectOverrides.StartLifeTime0p25);
			PoolManager.GetPoolItem<AnimEffect>("ChaosPortal").Play(currentPos, "Depart", 0.3f);
			string audioID = "ChaosLightningCrackle";
			Vector2? soundOrigin = currentPos;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, 0.2f, standardPitchRange);
			audioID = "EnemyDead";
			soundOrigin = currentPos;
			standardPitchRange = UnityEngine.Random.Range(1.1f, 1.2f);
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, 0.2f, standardPitchRange);
			UnityEngine.Object.Destroy(gameObject);
		}
	}
	public static void Create(Vector2 givenPos, Vector2 givenVec, string givenCat, string givenID)
	{
		PhantomRogue phantomRogue = Globals.ChaosInst<PhantomRogue>(Prefab, null, Globals.GetSafeLinecastVector(givenPos, givenVec, 0.75f, ChaosCollisions.layerAllWallAndObst));
		phantomRogue.initDashVec = givenVec;
		phantomRogue.atkCircle.SetAttackInfo(givenCat, givenID);
		phantomRogue.atkBox.SetAttackInfo(givenCat, givenID, 2);
	}
}
using System.Collections.Generic;
using Chaos.ListExtensions;
using UnityEngine;
public class PhantomSummoner : Entity
{
	private static GameObject prefab;
	public Transform bodyTrans;
	[HideInInspector]
	public Entity parentEnt;
	[HideInInspector]
	public List<GameObject> playerSummonsList;
	[HideInInspector]
	public string skillID = string.Empty;
	[HideInInspector]
	public Vector2 atkVector;
	private Vector2 currentPos;
	private int delayStopwatchID;
	private int destroyStopwatchID;
	private bool spawnCompleted;
	private bool atkStarted;
	private bool destroyQueued;
	private int maxAtkCount = 3;
	private PhantomOrb currentPO;
	private List<PhantomOrb> orbList = new List<PhantomOrb>();
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Effects/PhantomSummoner.prefab"));
	private bool OrbsExist
	{
		get
		{
			orbList.RemoveNullValues();
			return orbList.Count > 0;
		}
	}
	public override void Awake()
	{
		disablePreventFallCollider = true;
		base.Awake();
	}
	public override void Start()
	{
		base.Start();
		maxAtkCount = ((!Globals.RandBool) ? 3 : 4);
		FaceTarget(transform.position + (Vector3)atkVector, 2);
		SetXScale();
		anim.Play("Multicast", -1, 0f);
		delayStopwatchID = ChaosStopwatch.Begin(Random.Range(0.15f, 0.3f));
		spriteRenderer.material.SetColor("_OutlineColor", new Color(1f, 1f, 1f, 0.2f));
		currentPos = bodyTrans.position;
		PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(4, currentPos);
		PoolManager.GetPoolItem<AnimEffect>("ChaosPortal").Play(currentPos, "Spawn");
		ChaosBurst.Spawn(currentPos, 3);
	}
	public override void Update()
	{
		if (destroyQueued)
		{
			if (ChaosStopwatch.Check(destroyStopwatchID))
			{
				DestroySummoner();
			}
			return;
		}
		SetXScale();
		if (!ChaosStopwatch.Check(delayStopwatchID))
		{
			return;
		}
		if (!spawnCompleted)
		{
			spawnCompleted = true;
			currentPos = transform.position;
			for (int i = 0; i < 3; i++)
			{
				CreateOrb(currentPos, Globals.GetRotatedCircleVector(3, i, atkVector));
			}
		}
		else if (!atkStarted)
		{
			atkStarted = true;
			if (OrbsExist)
			{
				QueueOrbAttack();
			}
			else
			{
				QueueDestroy();
			}
		}
		else if (maxAtkCount > 0)
		{
			maxAtkCount--;
			atkStarted = maxAtkCount < 1;
			delayStopwatchID = ChaosStopwatch.Begin(Random.Range(0.5f, 0.625f));
		}
		else
		{
			QueueDestroy();
		}
	}
	private void CreateOrb(Vector2 givenPos, Vector2 givenVec)
	{
		currentPO = Globals.ChaosInst<PhantomOrb>(PhantomOrb.Prefab, null, Globals.GetSafeLinecastVector(givenPos, givenVec, 1.5f, ChaosCollisions.layerAllWallAndObst));
		currentPO.parentObj = parentEnt.gameObject;
		currentPO.attack.SetAttackInfo(skillCategory, skillID);
		orbList.Add(currentPO);
	}
	private void QueueOrbAttack()
	{
		for (int i = 0; i < orbList.Count; i++)
		{
			if (orbList[i] != null)
			{
				orbList[i].Attack(maxAtkCount <= 1);
			}
		}
		if (maxAtkCount <= 1)
		{
			orbList.Clear();
		}
	}
	private void QueueDestroy()
	{
		if (!destroyQueued)
		{
			destroyQueued = true;
			destroyStopwatchID = ChaosStopwatch.Begin(0.25f);
			anim.Play("Cast", -1, 0f);
			movement.EndMovement();
			currentPos = bodyTrans.position;
			PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(3, currentPos);
			SoundManager.PlayWithDistAndSPR("ChaosLightningCrackle", currentPos);
		}
	}
	private void DestroySummoner()
	{
		if (!(gameObject == null))
		{
			currentPos = bodyTrans.position;
			PoolManager.GetPoolItem<ParticleEffect>("ChaosChargeEffect").Emit(3, currentPos, ParticleEffectOverrides.StartLifeTime0p25);
			AnimEffect poolItem = PoolManager.GetPoolItem<AnimEffect>("ChaosPortal");
			Vector3 position = currentPos;
			string animName = "Depart";
			Vector3? localEulerAngles = new Vector3(0f, 0f, Random.Range(0f, 360f));
			poolItem.Play(position, animName, 0f, default, 1f, 1f, localEulerAngles);
			animName = "EnemyDead";
			Vector2? soundOrigin = currentPos;
			float overridePitch = Random.Range(1.1f, 1.2f);
			SoundManager.PlayAudioWithDistance(animName, soundOrigin, null, 24f, -1f, overridePitch);
			orbList.Clear();
			Object.Destroy(gameObject);
		}
	}
}

