	public class FollowState : State<ProjectileFamiliar>
	{
		private bool following;
		public FollowState(string stateName, FSM parentFSM, ProjectileFamiliar parentEntity)
			: base(stateName, parentFSM, parentEntity)
		{
		}
		public override void OnEnter()
		{
			parent.anim.Play("Idle");
			parent.FaceTarget(parent.parentTransform.position);
		}
		public override void Update()
		{
			if (Vector2.Distance(parent.parentTransform.position, parent.transform.position) > parent.followRadius)
			{
				following = true;
				parent.movement.MoveToTarget(parent.parentTransform);
			}
			else if (following)
			{
				parent.movement.EndMovement();
			}
		}
	}
	public class AttackState : State<ProjectileFamiliar>
	{
		private bool inPosition;
		private bool projectileSpawned;
		private Projectile currentProjectile;
		private Vector3 targetPosition;
		private Vector3 targetVector;
		public AttackState(string stateName, FSM parentFSM, ProjectileFamiliar parentEntity)
			: base(stateName, parentFSM, parentEntity)
		{
		}
		public override void OnEnter()
		{
			inPosition = false;
			projectileSpawned = false;
			parent.anim.Play("Attack");
			targetPosition = ((!(parent.attackTargetTrans == null)) ? parent.attackTargetTrans.position : ((Vector3)parent.attackTargetVector));
			parent.FaceTarget(targetPosition);
		}
		public override void Update()
		{
			if (!inPosition)
			{
				inPosition = parent.movement.MoveToTarget(parent.attackPositionVector);
				return;
			}
			parent.movement.EndMovement();
			if (FireProjectile())
			{
				fsm.ChangeState(fsm.defaultStateName);
			}
		}
		public override void OnExit()
		{
			if (currentProjectile != null)
			{
				PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(10, currentProjectile.transform.position);
				currentProjectile.anim.Play("Break");
				currentProjectile = null;
			}
			parent.attackTargetTrans = null;
		}
		public virtual bool FireProjectile()
		{
			if (currentProjectile == null)
			{
				if (projectileSpawned)
				{
					return true;
				}
				targetPosition = ((!(parent.attackTargetTrans == null)) ? parent.attackTargetTrans.position : ((Vector3)parent.attackTargetVector));
				currentProjectile = Object.Instantiate(parent.projectilePrefab, (targetPosition - parent.hurtBoxTransform.position).normalized * 0.5f + parent.hurtBoxTransform.position, Quaternion.identity).GetComponent<Projectile>();
				currentProjectile.attackBox.SetAttackInfo(parent.projSkillCategory, parent.projSkillID);
				projectileSpawned = true;
				parent.FaceTarget(targetPosition);
				return false;
			}
			if (currentProjectile.anim.AnimPlayed())
			{
				IceBall iceBall = currentProjectile as IceBall;
				targetVector = (targetPosition - currentProjectile.transform.position).normalized;
				iceBall.ReleaseIceBall(targetVector);
				currentProjectile = null;
				fsm.ChangeState(fsm.currentStateName);
				return true;
			}
			return false;
		}
	}
	[HideInInspector]
	public Entity parentEntity;
	[HideInInspector]
	public Transform parentTransform;
	[HideInInspector]
	public GameObject projectilePrefab;
	[HideInInspector]
	public string projSkillCategory;
	[HideInInspector]
	public string projSkillID;
	internal float followRadius = 2f;
	internal Vector2 attackPositionVector;
	internal Vector2 attackTargetVector;
	internal Transform attackTargetTrans;
	public void InitParams(Entity ent, Transform trans, GameObject projPrefab, string skillCat, string skillID)
	{
		parentEntity = ent;
		parentTransform = trans;
		projectilePrefab = projPrefab;
		projSkillCategory = skillCat;
		projSkillID = skillID;
	}
	public override void Start()
	{
		base.Start();
		InitFSM();
		attackPositionVector = Vector2.zero;
		attackTargetVector = Vector2.zero;
		hurtBoxTransform.name = ((!(parentEntity is Enemy)) ? Globals.allyHBStr : Globals.enemyHBStr);
	}
	private void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Follow";
		fsm.AddState(new FormState("Form", fsm, this));
		fsm.AddState(new FollowState("Follow", fsm, this));
		fsm.AddState(new AttackState("Attack", fsm, this));
		fsm.AddState(new DeadState("Dead", fsm, this));
		fsm.ChangeState("Form");
	}
	public override void Update()
	{
		if (parentTransform == null || parentEntity == null)
		{
			fsm.ChangeState("Dead");
		}
		else
		{
			base.Update();
		}
	}
	public void QueueAttack(Vector2 moveLocation, Vector2 shootLocation, Transform shootTransform = null)
	{
		if (!(fsm.currentStateName == "Dead"))
		{
			attackPositionVector = moveLocation;
			attackTargetVector = shootLocation;
			attackTargetTrans = shootTransform;
			fsm.QueueChangeState("Attack");
		}
	}
}
using System;
using System.Collections.Generic;
using Chaos.AnimatorExtensions;
