using UnityEngine;
public class ThunderSeeker : Seeker
{
	private static GameObject prefab;
	private LightningStrike currentStrike;
	private LightningStream currentStream;
	private int maxChainCount = 5;
	private int chainCounter;
	private bool targetHit;
	private TargetInfo foundTargetInfo;
	private Vector2 targetPosition = Vector2.zero;
	private Vector2 currentPosition = Vector2.zero;
	private List<GameObject> chainTargetList = new List<GameObject>();
	private ChaosQuickStopwatch lerpStopwatch = new ChaosQuickStopwatch(0.5f);
	private float lerpValue;
	private bool lerpCompleted;
	private ChaosQuickStopwatch delayStopwatch = new ChaosQuickStopwatch(0.25f);
	private bool delayCompleted;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/ThunderSeeker.prefab"));
	public override void Update()
	{
		if (!targetHit)
		{
			base.Update();
		}
	}
	public override void FixedUpdate()
	{
		if (targetHit)
		{
			if (!lerpCompleted)
			{
				lerpValue = lerpStopwatch.TimePercentage;
				transform.position = Vector2.Lerp(transform.position, targetPosition, lerpValue);
				if (lerpValue >= 1f)
				{
					lerpCompleted = true;
					delayStopwatch.IsRunning = true;
				}
			}
			else if (!delayCompleted && !delayStopwatch.IsRunning)
			{
				delayCompleted = true;
				targetHit = false;
				fsm.ChangeState("Dead");
			}
		}
		else
		{
			base.FixedUpdate();
		}
	}
	public override void HandleCollision(Entity givenEnt)
	{
		if (givenEnt == null)
		{
			return;
		}
		if (!isEmpowered)
		{
			currentStrike = Globals.ChaosInst<LightningStrike>(LightningStrike.Prefab, null, givenEnt.transform.position);
			currentStrike.attack.SetAttackInfo(attack.GetAtkInfoAtLevel(2));
			currentStrike.spawnLightningBurst = true;
			currentStrike.lightningBurstScale = 1.75f;
			base.HandleCollision(givenEnt);
		}
		else if (!chainTargetList.Contains(givenEnt.gameObject))
		{
			if (floorCollider != null)
			{
				floorContact.layer = LayerMask.NameToLayer("IgnoreEnemyAllyFloorContact");
			}
			if (targetHit)
			{
				CreateLightningStream(currentPosition, targetPosition);
			}
			targetHit = true;
			chainCounter++;
			chainTargetList.Add(givenEnt.gameObject);
			currentPosition = givenEnt.transform.position;
			foundTargetInfo = Entity.GetClosestTarget(targetList, currentPosition, 7f, playerTagOnly: false, chainTargetList, null, requireLOS: true, ChaosCollisions.layerAll);
			if (foundTargetInfo == null)
			{
				chainCounter = maxChainCount;
			}
			else
			{
				targetPosition = foundTargetInfo.position;
				lerpStopwatch.SetDelay(Vector2.Distance(targetPosition, currentPosition) * 0.1f, stopCurrent: false, autoStart: true);
				lerpCompleted = false;
				delayCompleted = false;
			}
			if (chainCounter >= maxChainCount)
			{
				base.HandleCollision(givenEnt);
			}
		}
	}
	public override void OnDead()
	{
		LightningBurst.CreateBurst(transform.position, string.Empty, string.Empty);
		base.OnDead();
	}
	private void CreateLightningStream(Vector2 givenPosition, Vector2 givenTarget)
	{
		currentStream = Globals.ChaosInst<LightningStream>(LightningStream.Prefab, null, givenPosition);
		currentStream.targetLocation = givenTarget;
	}
	public override void PlaySeekerAudio()
	{
		SoundManager.PlayWithDistAndSPR("SparkLoopShort", transform.position);
	}
}

