public class WindMinion : BasicMinion
{
	public class WindMinionAttackState : State<WindMinion>
	{
		private int windupStopwatchID;
		private ChaosQuickStopwatch delayStopwatch = new ChaosQuickStopwatch(0.5f);
		private bool windupComplete;
		private bool attackComplete;
		private bool delayComplete;
		private Vector2 targetVector;
		private Vector2 offsetVector;
		private ChaosQuickStopwatch attackTimer;
		private float attackInterval = 0.1f;
		public WindMinionAttackState(string newName, FSM newFSM, WindMinion newEnt)
			: base(newName, newFSM, newEnt)
		{
			attackTimer = new ChaosQuickStopwatch(attackInterval);
		}
		public override void OnEnter()
		{
			targetVector = (parent.closestTargetInfo.transform.position - parent.transform.position).normalized;
			offsetVector = Globals.GetPerpendicular(targetVector, Globals.RandBool);
			parent.movement.moveVector = targetVector;
			parent.movement.dashVector = targetVector;
			parent.movement.MoveToMoveVector(parent.movement.moveSpeedStat.CurrentValue * 0.25f);
			windupStopwatchID = ChaosStopwatch.Begin(parent.atkWindupTime);
			windupComplete = false;
			attackComplete = false;
			delayComplete = false;
			string audioID = "WindCircle";
			Vector2? soundOrigin = parent.transform.position;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
		}
		public override void FixedUpdate()
		{
			if (!windupComplete)
			{
				if (ChaosStopwatch.Check(windupStopwatchID))
				{
					windupComplete = true;
					PoolManager.GetPoolItem<DashAirBurst>().Burst(parent.transform.position + (Vector3)parent.movement.moveVector + Vector3.up, parent.movement.moveVector, useOffset: false);
					DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
					int particleCount = 12;
					float z = Globals.GetRotationVector(-parent.movement.moveVector).z;
					Vector3? emitPosition = parent.transform.position;
					poolItem.EmitDirBurst(particleCount, z, 12f, -1f, 0.4f, emitPosition);
					string audioID = "Spin";
					Vector2? soundOrigin = parent.transform.position;
					z = SoundManager.StandardPitchRange;
					SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, z);
				}
				return;
			}
			if (!attackComplete)
			{
				if (!parent.movement.DashToTarget())
				{
					return;
				}
				attackComplete = true;
				delayStopwatch.IsRunning = true;
			}
			if (!delayComplete)
			{
				delayComplete = !delayStopwatch.IsRunning;
				parent.movement.moveVector = Vector2.Lerp(targetVector, offsetVector, delayStopwatch.TimePercentage);
				parent.movement.MoveToMoveVector();
			}
			else
			{
				fsm.ChangeState("MoveToEnemy");
			}
		}
	}
