	private static float sctpuXAbs;
	private static float sctpuYAbs;
	private static float sctpuXDiff;
	private static float sctpuYDiff;
	public static Vector2 V2Position => (!(instance == null)) ? ((Vector2)instance.transform.position) : Vector2.zero;
	public bool HoriMoveOnly
	{
		get
		{
			return horiMoveOnly;
		}
		set
		{
			horiMoveOnly = value;
			if (value)
			{
				moveLockVector.y = transform.position.y;
			}
		}
	}
	public bool VertMoveOnly
	{
		get
		{
			return vertMoveOnly;
		}
		set
		{
			vertMoveOnly = value;
			if (value)
			{
				moveLockVector.x = transform.position.x;
			}
		}
	}
	public static CameraController Instance => instance;
	public void Awake()
	{
		if (instance != null && instance != this)
		{
			Object.Destroy(gameObject);
			return;
		}
		instance = this;
		Object.DontDestroyOnLoad(gameObject);
		spawnPos = transform.position;
		shakeDuration = 0.15f;
		shakeCounter = 0;
		shakeCounterMax = 4;
		lerp = false;
		lerpSpeed = 12f;
		overrideCameraUpdate = false;
		originalCameraSize = Camera.main.orthographicSize;
		blur = GetComponent<Blur>();
		blur.enabled = false;
		movement = GetComponent<Movement>();
		cameraHurtEffect = transform.Find("CameraHurtEffect").GetComponent<CameraHurtEffect>();
		cameraWorldTrans = transform.Find("CameraWorldPosition");
	}
	private void Update()
	{
		if (overrideCameraUpdate)
		{
			return;
		}
		Camera.main.orthographicSize = originalCameraSize;
		if (GameController.playerScripts[0] != null && GameController.playerScripts[1] != null)
		{
			if (p1Movement == null)
			{
				p1Movement = GameController.playerScripts[0].movement;
			}
			if (p2Movement == null)
			{
				p2Movement = GameController.playerScripts[1].movement;
			}
			playerDiff = GameController.playerScripts[0].transform.position - GameController.playerScripts[1].transform.position;
			distanceBetweenPlayers = playerDiff.magnitude;
			if (GameController.pvpOn || SceneManager.GetActiveScene().name.Contains("PvP"))
			{
				distanceBetweenPlayers *= 0.42f;
				Camera.main.orthographicSize = ((!(distanceBetweenPlayers > originalCameraSize)) ? originalCameraSize : distanceBetweenPlayers);
			}
			else if (GameController.coopOn)
			{
				if (GameController.PlayerIsDead())
				{
					distanceBetweenPlayers = -1f;
				}
				if (distanceBetweenPlayers > teleportToOtherPlayerRange)
				{
					Vector2 givenLocation = Vector2.zero;
					Player[] activePlayers = GameController.activePlayers;
					foreach (Player player in activePlayers)
					{
						if (player.playerID == 0)
						{
							givenLocation = player.transform.position;
						}
						else if (player.IsAvailable && !player.IsDead)
						{
							player.RequestTeleportMoveToLocation(givenLocation);
						}
					}
				}
				if (distanceBetweenPlayers > maxVerticalDistBetweenPlayers)
				{
					if (Mathf.Abs(playerDiff.y) > maxVerticalDistBetweenPlayers)
					{
						if (playerDiff.y > 0f)
						{
							p1Movement.preventUpMovement = true;
							p2Movement.preventDownMovement = true;
						}
						else
						{
							p1Movement.preventDownMovement = true;
							p2Movement.preventUpMovement = true;
						}
					}
					else
					{
						p1Movement.RemoveAllPrevents(xAxis: false);
						p2Movement.RemoveAllPrevents(xAxis: false);
					}
					if (Mathf.Abs(playerDiff.x) > maxHorizontalDistBetweenPlayers)
					{
						if (playerDiff.x > 0f)
						{
							p1Movement.preventRightMovement = true;
							p2Movement.preventLeftMovement = true;
						}
						else
						{
							p1Movement.preventLeftMovement = true;
							p2Movement.preventRightMovement = true;
						}
					}
					else
					{
						p1Movement.RemoveAllPrevents(xAxis: true, yAxis: false);
						p2Movement.RemoveAllPrevents(xAxis: true, yAxis: false);
					}
				}
				else
				{
					p1Movement.RemoveAllPrevents();
					p2Movement.RemoveAllPrevents();
				}
			}
		}
		if (disablePlayerTracking)
		{
			if (lockToSpawnPos)
			{
				transform.position = spawnPos;
			}
		}
		else
		{
			if (GameController.GetAlivePlayerCount() == 0)
			{
				return;
			}
			avgPlayerPos = GameController.GetPlayerPositionAverage();
			disableLockCamera = overrideCameraFollowPlayer && !HoriMoveOnly && !VertMoveOnly && Vector2.Distance(avgPlayerPos, transform.position) > 3f;
			if (lockCamera && !disableLockCamera)
			{
				if (cameraLockLocation == Vector3.zero)
				{
					cameraLockLocation = transform.position;
					lockedLocDistToPlayer = avgPlayerPos - cameraLockLocation;
					lockedLocDistToPlayer.z = 0f;
				}
				SetCameraPosition(avgPlayerPos - lockedLocDistToPlayer);
			}
			else if ((GameController.coopOn && distanceBetweenPlayers > 0f) || lerp)
			{
				LerpCamera(avgPlayerPos, lerpSpeed);
			}
			else
			{
				SetCameraPosition(avgPlayerPos);
			}
		}
	}
	public void SetCameraPosition(Vector3 newPosition)
